431	     * {@link OwnerDerivations#membershipNumber(String, LocalDate)} for the exact format.
432	     *
433	     * @return the membership number to assign
434	     */
435	    public String computeMembershipNumber() {
436	        return OwnerDerivations.membershipNumber(this.customerCode, this.registrationDate);
437	    }
438	
439	    /**
440	     * Compute the stable household identifier for this owner, derived deterministically
441	     * from its last name and postcode so every owner sharing a last name and postcode
442	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
443	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
444	     *
445	     * @return the household identifier
446	     */
447	    public String computeHouseholdId() {
448	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
449	    }
450	
451	    /**
452	     * Whether this owner belongs to the same household as {@code other}: that is, they
453	     * share the same last name and postcode. The last name is compared
454	     * case-insensitively with runs of whitespace collapsed to a single space (and
455	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
456	     * absent postcodes count as equal). Owners in the same household resolve to the same
457	     * {@link #computeHouseholdId() household identifier}.
458	     *
459	     * @param other the owner to compare against
460	     * @return {@code true} if both owners share a household
461	     */
462	    public boolean sameHouseholdAs(Owner other) {
463	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
464	            && Objects.equals(this.postcode, other.postcode);
465	    }
466	
467	    /**
468	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
469	     * trim, collapse internal runs of whitespace to a single space and lower-case.
470	     */
471	    private static String normalize(String value) {
472	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
473	    }
474	
475	    /**
476	     * Reduce an address to its canonical stored form. This is the value stored,
477	     * returned and used for every household comparison; see
478	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
479	     *
480	     * @param value the raw address (may be {@code null})
481	     * @return the normalised address, or the empty string if {@code value} is
482	     *         {@code null} or blank
483	     */
484	    public static String normalizeAddress(String value) {
485	        return OwnerDerivations.normalizeAddress(value);
486	    }
487	
488	    protected Set<Pet> getPetsInternal() {
489	        if (this.pets == null) {
490	            this.pets = new HashSet<>();
491	        }
492	        return this.pets;
493	    }
494	
495	    protected void setPetsInternal(Set<Pet> pets) {
496	        this.pets = pets;
497	    }
498	
499	    public List<Pet> getPets() {
500	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
501	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
502	        return Collections.unmodifiableList(sortedPets);
503	    }
504	
505	    public void setPets(List<Pet> pets) {
506	        this.pets = new HashSet<>(pets);
507	    }
508	
509	    public void addPet(Pet pet) {
510	        getPetsInternal().add(pet);
511	        pet.setOwner(this);
512	    }
513	
514	    /**
515	     * Return the Pet with the given name, or null if none found for this Owner.
516	     *
517	     * @param name to test
518	     * @return true if pet name is already in use
519	     */
520	    public Pet getPet(String name) {
521	        return getPet(name, false);
522	    }
523	
