526	     *
527	     * @param name to test
528	     * @return true if pet name is already in use
529	     */
530	    public Pet getPet(String name, boolean ignoreNew) {
531	        name = name.toLowerCase();
532	        for (Pet pet : getPetsInternal()) {
533	            if (!ignoreNew || !pet.isNew()) {
534	                String compName = pet.getName();
535	                compName = compName.toLowerCase();
536	                if (compName.equals(name)) {
